css:
*{box-sizing:border-box;margin:0;padding:0}
.pop{width:1055px;height:1491px;overflow:hidden}
.pop{font-family:"Hiragino Sans","Hiragino Kaku Gothic ProN",sans-serif;color:#1b2550;position:relative;
  background:radial-gradient(ellipse at 50% 0%,#ffe57a 0%,#ffd23a 55%,#ffc21f 100%)}
i{font-style:normal;display:inline-block}
.N{color:#1b2550}
/* ロゴ */
.logos{position:absolute;left:0;right:0;top:22px;display:flex;justify-content:center;align-items:center;gap:6px}
.logos img.d{height:150px}
.logos img.b{height:150px}
.x{font:900 52px/1 "Arial Black",sans-serif;color:#1b2550}
.catch{position:absolute;left:50%;top:190px;transform:translateX(-50%) rotate(-1.5deg);white-space:nowrap;
  font-weight:900;font-size:40px;color:#fff;background:#e8442c;padding:6px 36px 8px;border-radius:50px;
  border:5px solid #1b2550;box-shadow:6px 6px 0 #1b2550}
/* つながり */
.cyc{position:absolute;left:22px;right:22px;top:300px;height:400px}
.st{position:absolute;width:440px;height:166px;border-radius:30px;border:6px solid #1b2550;box-shadow:7px 7px 0 #1b2550;
  padding:0 18px 0 98px;display:flex;flex-direction:column;justify-content:center}
.st .n{position:absolute;left:18px;top:50%;transform:translateY(-50%);width:62px;height:62px;border-radius:50%;
  color:#fff;font:900 38px/56px "Arial Black";text-align:center;border:4px solid #1b2550}
.st b{display:block;font-size:33px;font-weight:900;line-height:1.2}
.st span{display:block;font-size:23px;font-weight:700;line-height:1.35;margin-top:6px;color:#2b3666}
.g{background:#d4f7cf}.g .n{background:#24a148}
.bl{background:#cfeaff}.bl .n{background:#1f86e6}
.y{background:#fff3b8}.y .n{background:#f29a00}
.ar{position:absolute;width:0;height:0}
/* 2列 */
.col{position:absolute;top:672px;width:492px;height:580px;background:#fff;border-radius:30px;border:6px solid #1b2550;
  box-shadow:7px 7px 0 #1b2550;overflow:hidden}
.col .hd{height:118px;display:flex;align-items:center;justify-content:center;border-bottom:6px solid #1b2550}
.col .hd img{height:96px}
.cd .hd{background:#2fb35a}.cb .hd{background:#3a9bf0}
.col ul{list-style:none;padding:8px 22px 0;height:450px;display:flex;flex-direction:column;justify-content:space-around}
.col li{font-size:25px;font-weight:700;line-height:1.35;padding:6px 0;border-bottom:3px dotted #c9cfe0;text-align:center}
.col li:last-child{border-bottom:0}
.free{font-size:44px!important;font-weight:900!important;color:#e8442c;padding-top:2px!important}
.hit{font-size:23px!important}
.hit em{display:block;font-style:normal;font-size:40px;font-weight:900;color:#e8442c;line-height:1.2}
.tag{display:inline-block;background:#e8442c;color:#fff;font-weight:900;border-radius:20px;padding:0 14px;font-size:24px;margin-left:4px}
.new{position:absolute;right:12px;top:10px;background:#ffd23a;color:#e8442c;font-weight:900;font-size:22px;border:4px solid #1b2550;
  border-radius:20px;padding:0 12px;transform:rotate(10deg)}
.note{font-size:19px!important;color:#4a5478;font-weight:700!important}
/* BPT */
.bpt{position:absolute;left:22px;right:22px;top:1274px;bottom:20px;background:#fff;border-radius:30px;border:6px solid #1b2550;
  box-shadow:7px 7px 0 #1b2550;padding:0 24px 0 210px;display:flex;flex-direction:column;justify-content:center}
.bpt .coin{position:absolute;left:26px;top:50%;transform:translateY(-50%);width:150px;height:150px;border-radius:50%;
  background:radial-gradient(circle at 35% 30%,#fff2a8,#ffc21f 60%,#e09a00);border:6px solid #1b2550;
  display:flex;align-items:center;justify-content:center;flex-direction:column;font-weight:900;color:#1b2550}
.coin b{font:900 46px/1 "Arial Black";}
.coin small{font-size:19px;margin-top:6px}
.bpt p{font-size:26px;font-weight:800;line-height:1.25;padding:2px 0}
.bpt p em{font-style:normal;color:#e8442c;font-weight:900}
.bpt p.s{font-size:22px;font-weight:700;color:#2b3666}

.flow{position:absolute;left:22px;right:22px;top:318px;height:340px}
.fs{position:absolute;top:8px;width:300px;height:230px;border-radius:30px;border:6px solid #1b2550;box-shadow:7px 7px 0 #1b2550;
  text-align:center;padding:10px 10px 0;display:flex;flex-direction:column;justify-content:center}
.fs:nth-child(1){left:0}.fs:nth-child(2){left:355px}
.fs.main{left:710px;width:301px;background:#fff3b8;border-color:#e8442c}
.fs .n{position:absolute;left:50%;top:-24px;transform:translateX(-50%);width:56px;height:56px;border-radius:50%;color:#fff;
  font:900 34px/48px "Arial Black";text-align:center;border:4px solid #1b2550;background:#1f86e6}
.fs.main .n{background:#e8442c}
.fs b{display:block;font-size:32px;font-weight:900;line-height:1.2}
.fs.main b{font-size:40px;color:#e8442c}
.fs span{display:block;font-size:23px;font-weight:700;line-height:1.35;margin-top:10px;color:#2b3666}
.fs em{font-style:normal;font-weight:900}
.bpt-c{color:#1667c8;font-size:27px}
.big3{white-space:nowrap;font-size:22px;color:#1b2550;background:#fff;border:4px solid #1b2550;border-radius:16px;padding:2px 12px;display:inline-block}
.ex{position:absolute;left:0;right:0;top:262px;background:#fff;border:5px solid #1b2550;border-radius:40px;text-align:center;
  font-size:26px;font-weight:900;padding:8px 78px 8px;white-space:nowrap;box-shadow:6px 6px 0 #1b2550}
.ex em{font-style:normal;color:#e8442c;font-size:30px}
.exl{position:absolute;left:14px;top:50%;transform:translateY(-50%);background:#1b2550;color:#fff;border-radius:50%;width:54px;height:54px;line-height:54px;font-size:28px}
.exs{display:block;text-align:center;font-size:20px;font-weight:800;color:#3a4470;margin-top:2px}
.bpt p.cap{display:inline-block;align-self:flex-start;background:#e8442c;color:#fff;border:4px solid #1b2550;border-radius:30px;padding:1px 18px 3px;margin:4px 0 6px;font-size:25px}
.bpt p.cap b{font-size:30px;color:#ffe066;font-weight:900}
.bpt p.cap .cs{font-size:20px;font-weight:800}
.cd li{padding:4px 0!important;font-size:25px}
.cd li.free{font-size:40px!important}
.cd li.hit em{font-size:37px}
li.max{line-height:1.2!important}
li.max b{color:#e8442c;font-size:30px}
li.max small{font-size:18px;color:#4a5478}
